import test from 'node:test';
import assert from 'node:assert/strict';
import { lineTotal, lineDiscount, lineVat, invoiceTotals, isValidDiscountPercent } from '../src/totals.js';

test('lineTotal returns qty * unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 9500 }), 47500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 10, unitPrice: 1000 }), 10000);
});

test('lineTotal with zero quantity', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 9500 }), 0);
});

test('lineTotal ignores other line properties', () => {
  assert.equal(
    lineTotal({
      qty: 5,
      unitPrice: 9500,
      name: 'Development (hour)',
      sku: 'DEV-HOUR',
      vatRate: 21,
      discountPercent: 5,
    }),
    47500
  );
});

test('lineDiscount returns 0 for no discount', () => {
  assert.equal(lineDiscount({ qty: 5, unitPrice: 9500 }), 0);
  assert.equal(lineDiscount({ qty: 5, unitPrice: 9500, discountPercent: 0 }), 0);
});

test('lineDiscount calculates percentage discount and rounds', () => {
  // 5 * 9500 = 47500, discount 5% = 2375
  assert.equal(lineDiscount({ qty: 5, unitPrice: 9500, discountPercent: 5 }), 2375);
  // 1 * 120000 = 120000, discount 5% = 6000
  assert.equal(lineDiscount({ qty: 1, unitPrice: 120000, discountPercent: 5 }), 6000);
});

test('lineDiscount with decimal discount percent', () => {
  // 5 * 9500 = 47500, discount 2.5% = 1187.5 rounds to 1188
  assert.equal(lineDiscount({ qty: 5, unitPrice: 9500, discountPercent: 2.5 }), 1188);
});

test('lineDiscount never negative', () => {
  const line = { qty: 5, unitPrice: 9500, discountPercent: 5 };
  assert(lineDiscount(line) >= 0);
});

test('lineDiscount with bulk discount at qty 10', () => {
  // 10 * 10000 = 100000, no line discount, bulk 2.5% = 2500
  assert.equal(lineDiscount({ qty: 10, unitPrice: 10000 }), 2500);
});

test('lineDiscount with bulk discount at qty 11', () => {
  // 11 * 10000 = 110000, no line discount, bulk 2.5% = 2750
  assert.equal(lineDiscount({ qty: 11, unitPrice: 10000 }), 2750);
});

test('lineDiscount with bulk discount at qty 20', () => {
  // 20 * 10000 = 200000, no line discount, bulk 2.5% = 5000
  assert.equal(lineDiscount({ qty: 20, unitPrice: 10000 }), 5000);
});

test('lineDiscount without bulk discount at qty 9', () => {
  // 9 * 10000 = 90000, no line discount, no bulk (qty < 10) = 0
  assert.equal(lineDiscount({ qty: 9, unitPrice: 10000 }), 0);
});

test('lineDiscount bulk discount applied after line discount', () => {
  // 10 * 10000 = 100000, line discount 10% = 10000, after = 90000
  // bulk 2.5% of 90000 = 2250
  // total discount = 10000 + 2250 = 12250
  assert.equal(lineDiscount({ qty: 10, unitPrice: 10000, discountPercent: 10 }), 12250);
});

test('lineDiscount bulk discount applied after tier discount', () => {
  // 10 * 9500 = 95000, tier discount (5% stored as discountPercent) = 4750, after = 90250
  // bulk 2.5% of 90250 = 2256.25 rounds to 2256
  // total discount = 4750 + 2256 = 7006
  assert.equal(lineDiscount({ qty: 10, unitPrice: 9500, discountPercent: 5 }), 7006);
});

test('lineDiscount with large quantity', () => {
  // 100 * 5000 = 500000, no line discount, bulk 2.5% = 12500
  assert.equal(lineDiscount({ qty: 100, unitPrice: 5000 }), 12500);
});

test('lineDiscount with high line discount and bulk', () => {
  // 10 * 10000 = 100000, line discount 50% = 50000, after = 50000
  // bulk 2.5% of 50000 = 1250
  // total discount = 50000 + 1250 = 51250
  assert.equal(lineDiscount({ qty: 10, unitPrice: 10000, discountPercent: 50 }), 51250);
});

test('lineDiscount bulk discount rounds correctly', () => {
  // 10 * 9500 = 95000, no discount
  // bulk 2.5% of 95000 = 2375
  assert.equal(lineDiscount({ qty: 10, unitPrice: 9500 }), 2375);
});

test('lineVat returns 0 for no VAT rate', () => {
