test('renderInvoiceText with multiple items and VAT', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier: no discount
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 }, // 95.00, 21% VAT = 19.95
      { sku: 'PRINT-A4', qty: 100 }, // 37.00, 9% VAT = 3.33
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  // Should show VAT line
