test('renderInvoiceText shows subtotal and discount in total line when discounts present', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier: no tier discount
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 20 }, // 21% VAT
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 10 }, // 21% VAT
    ],
  });

  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);

  const lines = text.split('\n');
  const totalLine = lines[lines.length - 1];

