test('applyVoucher reduces total in invoiceTotals', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const totalsWithoutVoucher = invoiceTotals(result.value);

  const vouchResult = applyVoucher(result.value, { code: 'SAVE10', amount: 5000 });
