test('invoiceTotals with voucher reduces total correctly', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier: no discount
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  const vouchResult = applyVoucher(result.value, { code: 'SAVE10', amount: 5000 });
  assert.equal(vouchResult.ok, true);

  const totals = invoiceTotals(vouchResult.value);

  // DEV-HOUR: 95.00, 21% VAT = 19.95
  // Total = 95 + 19.95 = 114.95
  // With voucher = 114.95 - 50 = 64.95
  assert.equal(totals.subtotal, 9500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 1995);
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, 6495);
});
